<?php blog_head('Journal categories', 'Private Bed Mesh publishing categories.', true); ?>
<main class="blog-shell blog-admin-shell" id="blog-main"><?php blog_admin_navigation('categories'); ?><header class="blog-admin-header"><div><p class="blog-eyebrow">Give each idea a home</p><h1><?= $action === 'add' ? 'Create a category' : ($action === 'edit' ? 'Edit category' : ($action === 'delete' ? 'Delete category' : 'Categories')) ?></h1></div><?php if ($action === 'view'): ?><a class="button" href="<?= esc(blog_url('admin/categories/add')) ?>">Add category <span aria-hidden="true">＋</span></a><?php else: ?><a href="<?= esc(blog_url('admin/categories')) ?>">← All categories</a><?php endif; ?></header><?php if ($flash): ?><p class="blog-notice" role="status"><?= esc($flash) ?></p><?php endif; ?><?php if ($errors): ?><div class="blog-notice blog-notice--error" role="alert"><?php foreach ($errors as $error): ?><p><?= esc($error) ?></p><?php endforeach; ?></div><?php endif; ?>
<?php if ($action === 'delete'): ?><section class="blog-confirm"><h2><?= esc($record['category']) ?></h2><p>A category can be deleted once all its articles have been moved elsewhere. Hiding it instead removes its articles from public lists and direct public pages.</p><form method="post"><?= csrf_field() ?><div class="blog-actions"><button type="submit" class="button blog-danger">Delete category</button><a href="<?= esc(blog_url('admin/categories')) ?>">Keep category</a></div></form></section>
<?php elseif (in_array($action, ['add', 'edit'], true)): ?><form method="post" class="blog-category-form"><?= csrf_field() ?><label for="category-name">Category name<input id="category-name" name="category" type="text" required maxlength="50" value="<?= blog_form_value($record, 'category') ?>"></label><label class="blog-check"><input type="checkbox" name="disabled" value="1"<?= ($_POST['disabled'] ?? (!$isPost ? ($record['disabled'] ?? 0) : 0)) ? ' checked' : '' ?>> Hide this category and its articles from the public journal</label><p class="blog-editor-note">Drafts stay private regardless of their category. Hiding a category also hides its published articles.</p><button class="button" type="submit">Save category</button></form>
<?php else: ?><div class="blog-admin-table-wrap"><table class="blog-admin-table"><thead><tr><th scope="col">Category</th><th scope="col">Visibility</th><th scope="col">Articles</th><th scope="col">Actions</th></tr></thead><tbody><?php foreach ($categories as $item): ?><tr><th scope="row"><?= esc($item['category']) ?><small><?= esc($item['slug']) ?></small></th><td><?= $item['disabled'] ? 'Hidden' : 'Visible' ?></td><td><?= (int) $item['total'] ?></td><td><a href="<?= esc(blog_url('admin/categories/edit/' . $item['id'])) ?>">Edit</a><a href="<?= esc(blog_url('admin/categories/delete/' . $item['id'])) ?>">Delete</a></td></tr><?php endforeach; ?></tbody></table><?php if (!$categories): ?><p class="blog-table-empty">Add a category before writing your first article.</p><?php endif; ?></div><?php endif; ?></main><?php blog_foot(); ?>
